","variante":"Cambiare punteggio, vincoli, segnali, fondamentale richiesto, numero di giocatori, durata o obiettivo secondario.","coaching_points":"Mantenere chiaro lo scopo della proposta; qualità prima della velocità; adattarsi senza perdere postura e riferimenti; favorire autonomia e decisione.","errori_comuni":"Trasformare il tema libero in un esercizio specialistico già presente; inserire troppi vincoli; privilegiare velocità a scapito della qualità; obiettivo non chiaro.","schema_url":null,"foto_url":null,"attivo":true,"schema_step_1":"Definire il tema o la sfida.","schema_step_2":"Spiegare regole e vincoli.","schema_step_3":"Avviare la sequenza multi-obiettivo.","schema_step_4":"Adattare la risposta agli stimoli.","schema_step_5":"Valutare qualità, decisione e risultato.","schema_step_6":null,"scenario_gara":null,"numero_azioni":null},{"codice":"GK-TL-040","nome":"Tema libero finale: scenario aperto","categoria":"Tema libero","sottocategoria":"Scenario aperto","fase":"Situazionale","obiettivo":"Chiudere la seduta con uno scenario libero in cui emergono spontaneamente più comportamenti.","descrizione":"Situazione libera o semi-aperta di tema libero finale: scenario aperto, progettata per integrare più obiettivi tecnici, decisionali e fisici senza duplicare una categoria specialistica.","durata_min":14,"portieri_min":2,"portieri_max":8,"intensita":"Alta","difficolta":4,"materiale":"8-14 palloni, porta, coni/cinesini, casacche, porticine/bersagli; materiale variabile secondo il tema","variante":"Cambiare punteggio, vincoli, segnali, fondamentale richiesto, numero di giocatori, durata o obiettivo secondario.","coaching_points":"Mantenere chiaro lo scopo della proposta; qualità prima della velocità; adattarsi senza perdere postura e riferimenti; favorire autonomia e decisione.","errori_comuni":"Trasformare il tema libero in un esercizio specialistico già presente; inserire troppi vincoli; privilegiare velocità a scapito della qualità; obiettivo non chiaro.","schema_url":null,"foto_url":null,"attivo":true,"schema_step_1":"Definire il tema o la sfida.","schema_step_2":"Spiegare regole e vincoli.","schema_step_3":"Avviare la sequenza multi-obiettivo.","schema_step_4":"Adattare la risposta agli stimoli.","schema_step_5":"Valutare qualità, decisione e risultato.","schema_step_6":null,"scenario_gara":null,"numero_azioni":null}]$catalog_json$::jsonb;
  imported_count integer;
  taxonomy_count integer;
  resolved_taxonomy_count integer;
  match_simulation_count integer;
begin
  if to_regclass('public.exercise_categories') is null
     or to_regclass('public.exercise_subcategories') is null
     or to_regclass('public.exercises') is null then
    raise exception 'FASE C annullata: esegui prima le migration precedenti.';
  end if;

  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'exercises' and column_name = 'scenario_gara'
  ) or not exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'exercises' and column_name = 'numero_azioni'
  ) then
    raise exception 'FASE C annullata: la Fase A non risulta applicata.';
  end if;

  if exists (
    select 1
    from (values
      (1, 'Tecnica presa alta e rasoterra', 'Tecnica presa alta e rasoterra'),
      (2, 'Tuffi laterali e reattività', 'Tuffi laterali e reattività'),
      (3, 'Uscite basse e 1vs1', 'Uscite basse 1vs1'),
      (4, 'Reattività con ostacoli e tuffi', 'Reattività con ostacoli e tuffi'),
      (5, 'Uscite alte e palle aeree', 'Uscite alte su cross'),
      (6, 'Tecnica di piede', 'Tecnica piede'),
      (7, 'Parate ravvicinate', 'Parate ravvicinate'),
      (9, 'Match Simulation', 'Match Simulation'),
      (10, 'Tecnica 1v1 - copertura angoli', 'Tecnica 1vs1 / copertura angoli'),
      (11, 'Posizionamento porta', 'Posizionamento porta'),
      (12, 'Tema libero', 'Tema libero')
    ) as expected(id, official_name, legacy_name)
    left join public.exercise_categories current_category on current_category.id = expected.id
    where current_category.id is null
       or current_category.nome not in (expected.official_name, expected.legacy_name)
  ) then
    raise exception 'FASE C annullata: gli ID delle categorie non corrispondono alla struttura attesa.';
  end if;

  if exists (
    select 1
    from (values
      (1, 'Tecnica presa alta e rasoterra', 'Tecnica presa alta e rasoterra'),
      (2, 'Tuffi laterali e reattività', 'Tuffi laterali e reattività'),
      (3, 'Uscite basse e 1vs1', 'Uscite basse 1vs1'),
      (4, 'Reattività con ostacoli e tuffi', 'Reattività con ostacoli e tuffi'),
      (5, 'Uscite alte e palle aeree', 'Uscite alte su cross'),
      (6, 'Tecnica di piede', 'Tecnica piede'),
      (7, 'Parate ravvicinate', 'Parate ravvicinate'),
      (9, 'Match Simulation', 'Match Simulation'),
      (10, 'Tecnica 1v1 - copertura angoli', 'Tecnica 1vs1 / copertura angoli'),
      (11, 'Posizionamento porta', 'Posizionamento porta'),
      (12, 'Tema libero', 'Tema libero')
    ) as expected(id, official_name, legacy_name)
    join public.exercise_categories conflicting_category
      on conflicting_category.nome = expected.official_name
     and conflicting_category.id <> expected.id
  ) then
    raise exception 'FASE C annullata: un nome categoria ufficiale è già assegnato a un altro ID.';
  end if;

  update public.exercise_categories as category
  set nome = expected.official_name,
      attivo = true
  from (values
      (1, 'Tecnica presa alta e rasoterra', 'Tecnica presa alta e rasoterra'),
      (2, 'Tuffi laterali e reattività', 'Tuffi laterali e reattività'),
      (3, 'Uscite basse e 1vs1', 'Uscite basse 1vs1'),
      (4, 'Reattività con ostacoli e tuffi', 'Reattività con ostacoli e tuffi'),
      (5, 'Uscite alte e palle aeree', 'Uscite alte su cross'),
      (6, 'Tecnica di piede', 'Tecnica piede'),
      (7, 'Parate ravvicinate', 'Parate ravvicinate'),
      (9, 'Match Simulation', 'Match Simulation'),
      (10, 'Tecnica 1v1 - copertura angoli', 'Tecnica 1vs1 / copertura angoli'),
      (11, 'Posizionamento porta', 'Posizionamento porta'),
      (12, 'Tema libero', 'Tema libero')
  ) as expected(id, official_name, legacy_name)
  where category.id = expected.id
    and (category.nome is distinct from expected.official_name or category.attivo is distinct from true);

  -- Allinea anche il testo categoria duplicato negli esercizi già presenti.
  update public.exercises as exercise
  set categoria = category.nome,
      updated_at = now()
  from public.exercise_categories as category
  where exercise.category_id = category.id
    and category.id in (3, 5, 6, 10)
    and exercise.categoria is distinct from category.nome;

  insert into public.exercise_subcategories (category_id, nome, fase, attivo)
  select distinct category.id, master.sottocategoria, master.fase, true
  from jsonb_to_recordset(catalog_data) as master(
      codice text, nome text, categoria text, sottocategoria text, fase text,
      obiettivo text, descrizione text, durata_min integer, portieri_min integer,
      portieri_max integer, intensita text, difficolta integer, materiale text,
      variante text, coaching_points text, errori_comuni text, schema_url text,
      foto_url text, attivo boolean, schema_step_1 text, schema_step_2 text,
      schema_step_3 text, schema_step_4 text, schema_step_5 text,
      schema_step_6 text, scenario_gara text, numero_azioni text
)
  join public.exercise_categories as category on category.nome = master.categoria
  on conflict (category_id, nome, fase) do update set attivo = true;

  select count(*) into taxonomy_count
  from (
    select distinct master.categoria, master.sottocategoria, master.fase
    from jsonb_to_recordset(catalog_data) as master(
      codice text, nome text, categoria text, sottocategoria text, fase text,
      obiettivo text, descrizione text, durata_min integer, portieri_min integer,
      portieri_max integer, intensita text, difficolta integer, materiale text,
      variante text, coaching_points text, errori_comuni text, schema_url text,
      foto_url text, attivo boolean, schema_step_1 text, schema_step_2 text,
      schema_step_3 text, schema_step_4 text, schema_step_5 text,
      schema_step_6 text, scenario_gara text, numero_azioni text
)
  ) as taxonomy;

  select count(*) into resolved_taxonomy_count
  from (
    select distinct master.categoria, master.sottocategoria, master.fase
    from jsonb_to_recordset(catalog_data) as master(
      codice text, nome text, categoria text, sottocategoria text, fase text,
      obiettivo text, descrizione text, durata_min integer, portieri_min integer,
      portieri_max integer, intensita text, difficolta integer, materiale text,
      variante text, coaching_points text, errori_comuni text, schema_url text,
      foto_url text, attivo boolean, schema_step_1 text, schema_step_2 text,
      schema_step_3 text, schema_step_4 text, schema_step_5 text,
      schema_step_6 text, scenario_gara text, numero_azioni text
)
  ) as master_taxonomy
  join public.exercise_categories as category on category.nome = master_taxonomy.categoria
  join public.exercise_subcategories as subcategory
    on subcategory.category_id = category.id
   and subcategory.nome = master_taxonomy.sottocategoria
   and subcategory.fase = master_taxonomy.fase;

  if taxonomy_count <> 248 or resolved_taxonomy_count <> 248 then
    raise exception 'FASE C annullata: tassonomia incompleta (% su 248).', resolved_taxonomy_count;
  end if;

  insert into public.exercises as target (
    codice, nome, category_id, subcategory_id, categoria, sottocategoria, fase,
    obiettivo, descrizione, durata_min, portieri_min, portieri_max, intensita,
    difficolta, materiale, variante, coaching_points, errori_comuni,
    schema_url, foto_url, attivo, schema_step_1, schema_step_2, schema_step_3,
    schema_step_4, schema_step_5, schema_step_6, scenario_gara, numero_azioni
  )
  select
    master.codice, master.nome, category.id, subcategory.id, master.categoria,
    master.sottocategoria, master.fase, master.obiettivo, master.descrizione,
    master.durata_min, master.portieri_min, master.portieri_max, master.intensita,
    master.difficolta, master.materiale, master.variante, master.coaching_points,
    master.errori_comuni, nullif(master.schema_url, ''), nullif(master.foto_url, ''),
    master.attivo, master.schema_step_1, master.schema_step_2, master.schema_step_3,
    master.schema_step_4, master.schema_step_5, master.schema_step_6,
    master.scenario_gara, master.numero_azioni
  from jsonb_to_recordset(catalog_data) as master(
      codice text, nome text, categoria text, sottocategoria text, fase text,
      obiettivo text, descrizione text, durata_min integer, portieri_min integer,
      portieri_max integer, intensita text, difficolta integer, materiale text,
      variante text, coaching_points text, errori_comuni text, schema_url text,
      foto_url text, attivo boolean, schema_step_1 text, schema_step_2 text,
      schema_step_3 text, schema_step_4 text, schema_step_5 text,
      schema_step_6 text, scenario_gara text, numero_azioni text
)
  join public.exercise_categories as category on category.nome = master.categoria
  join public.exercise_subcategories as subcategory
    on subcategory.category_id = category.id
   and subcategory.nome = master.sottocategoria
   and subcategory.fase = master.fase
  on conflict (codice) do update set
    nome = excluded.nome,
    category_id = excluded.category_id,
    subcategory_id = excluded.subcategory_id,
    categoria = excluded.categoria,
    sottocategoria = excluded.sottocategoria,
    fase = excluded.fase,
    obiettivo = excluded.obiettivo,
    descrizione = excluded.descrizione,
    durata_min = excluded.durata_min,
    portieri_min = excluded.portieri_min,
    portieri_max = excluded.portieri_max,
    intensita = excluded.intensita,
    difficolta = excluded.difficolta,
    materiale = excluded.materiale,
    variante = excluded.variante,
    coaching_points = excluded.coaching_points,
    errori_comuni = excluded.errori_comuni,
    schema_url = coalesce(nullif(excluded.schema_url, ''), target.schema_url),
    foto_url = coalesce(nullif(excluded.foto_url, ''), target.foto_url),
    attivo = excluded.attivo,
    schema_step_1 = excluded.schema_step_1,
    schema_step_2 = excluded.schema_step_2,
    schema_step_3 = excluded.schema_step_3,
    schema_step_4 = excluded.schema_step_4,
    schema_step_5 = excluded.schema_step_5,
    schema_step_6 = excluded.schema_step_6,
    scenario_gara = excluded.scenario_gara,
    numero_azioni = excluded.numero_azioni,
    updated_at = now();

  select count(*) into imported_count
  from public.exercises as exercise
  join jsonb_to_recordset(catalog_data) as master(
      codice text, nome text, categoria text, sottocategoria text, fase text,
      obiettivo text, descrizione text, durata_min integer, portieri_min integer,
      portieri_max integer, intensita text, difficolta integer, materiale text,
      variante text, coaching_points text, errori_comuni text, schema_url text,
      foto_url text, attivo boolean, schema_step_1 text, schema_step_2 text,
      schema_step_3 text, schema_step_4 text, schema_step_5 text,
      schema_step_6 text, scenario_gara text, numero_azioni text
)
    on master.codice = exercise.codice;

  if imported_count <> 460 then
    raise exception 'FASE C annullata: attesi 460 esercizi MASTER, trovati %.', imported_count;
  end if;

  if exists (
    select codice from public.exercises group by codice having count(*) > 1
  ) then
    raise exception 'FASE C annullata: sono presenti codici esercizio duplicati.';
  end if;

  select count(*) into match_simulation_count
  from public.exercises as exercise
  join jsonb_to_recordset(catalog_data) as master(
      codice text, nome text, categoria text, sottocategoria text, fase text,
      obiettivo text, descrizione text, durata_min integer, portieri_min integer,
      portieri_max integer, intensita text, difficolta integer, materiale text,
      variante text, coaching_points text, errori_comuni text, schema_url text,
      foto_url text, attivo boolean, schema_step_1 text, schema_step_2 text,
      schema_step_3 text, schema_step_4 text, schema_step_5 text,
      schema_step_6 text, scenario_gara text, numero_azioni text
)
    on master.codice = exercise.codice
  where exercise.categoria = 'Match Simulation'
    and exercise.scenario_gara is not null
    and exercise.numero_azioni is not null;

  if match_simulation_count <> 60 then
    raise exception 'FASE C annullata: i 60 Match Simulation non risultano completi.';
  end if;
end
$phase_c$;

commit;

select
  'FASE C COMPLETATA' as risultato,
  460 as esercizi_master_presenti,
  248 as combinazioni_tassonomiche_master,
  60 as match_simulation_presenti,
  count(*) as esercizi_totali_database
from public.exercises;
